/**
 * Element locals.tf contribution — ei emits only title/id system lookups
 * for `elementum_element` (no status/stage maps).
 */
import { expr } from "../../engine/tf/index.js";
import { ELEMENT_RESOURCE_TYPE } from "./module.js";
/** Append one element's system lookup locals, keyed by its namespace (= tfLabel). */
export function appendElementLocals(attrs, ns) {
    const element = (path) => expr.resourceAttr(ELEMENT_RESOURCE_TYPE, ns, [path]);
    attrs[`${ns}_title_field_id`] = element("title_field_id");
    attrs[`${ns}_id_field_id`] = element("id_field_id");
}
